<template>
  <div><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><TeacherClassSelector v-if="!selectedClassId" :classes="classes" :loading="loading" title="Báo cáo lớp học" description="Chọn một lớp để xem báo cáo và các chỉ số tổng hợp." feature-count-label="hoạt động" @select="selectClass" /><template v-else><div class="toolbar page-toolbar"><div class="class-context"><strong>{{ selectedClassLabel }}</strong><button class="mini-button" @click="changeClass">Đổi lớp</button></div><div class="toolbar-actions"><span class="cell-subtle">Cập nhật {{ report?.updatedAt ? formatDateTime(report.updatedAt) : '—' }}</span></div></div><div v-if="loading" class="loading-state">Đang tải báo cáo…</div><template v-else-if="report"><div class="metrics-grid"><MetricCard icon="♙" label="Người học đang hoạt động" :value="report.activeEnrollmentCount" :hint="`${report.enrollmentCount} lượt ghi danh`" /><MetricCard icon="✓" label="Điểm đã công bố" :value="report.publishedGradeCount" hint="Sổ điểm" /><MetricCard icon="◒" label="Điểm trung bình" :value="`${report.averageScorePercent}%`" hint="Theo dữ liệu tổng hợp của lớp" /><MetricCard icon="◷" label="Điểm danh" :value="`${report.attendancePercentage}%`" hint="Theo dữ liệu tổng hợp điểm danh" /></div><div class="grid-two"><section class="panel"><div class="panel-heading"><h2>Tình hình đánh giá</h2><span>{{ report.publishedActivityCount }}/{{ report.activityCount }} đã công bố</span></div><div class="progress-row"><div class="progress-row-head"><span>Bài nộp</span><strong>{{ report.submissionCount }}</strong></div><div class="progress-track"><div class="progress-fill" :style="{ width: `${Math.min(100, report.submissionCount ? 100 : 0)}%` }"></div></div></div><div class="progress-row"><div class="progress-row-head"><span>Yêu cầu hỗ trợ</span><strong>{{ report.overviewHelpRequestedCount }}</strong></div></div><div class="progress-row"><div class="progress-row-head"><span>Đang thực hiện</span><strong>{{ report.overviewInProgressCount }}</strong></div></div></section><section class="panel"><div class="panel-heading"><h2>Điểm danh</h2><span>{{ report.attendanceSessionCount }} buổi</span></div><div class="list-compact"><div class="list-compact-item"><div><strong>Có mặt</strong><span>{{ report.attendancePresentCount }}</span></div><StatusPill value="Present" /></div><div class="list-compact-item"><div><strong>Muộn</strong><span>{{ report.attendanceLateCount }}</span></div><StatusPill value="Late" /></div><div class="list-compact-item"><div><strong>Vắng</strong><span>{{ report.attendanceAbsentCount }}</span></div><StatusPill value="Absent" /></div></div></section></div></template><div v-else class="panel empty-state"><strong>Chưa có dữ liệu báo cáo</strong><span>Lớp chưa có dữ liệu để tổng hợp.</span></div></template></div>
</template>
<script setup lang="ts">
import { errorMessage } from '../../../shared/api/http'
import { computed, onMounted, ref, watch } from 'vue'; import MetricCard from '../../../shared/ui/MetricCard.vue'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import TeacherClassSelector from '../../../shared/ui/TeacherClassSelector.vue'; import { academicsApi, reportingApi } from '../../../shared/api/client'; import { formatDateTime, type ClassReport, type LearningClass } from '../../../shared/types'
const classes = ref<LearningClass[]>([]); const selectedClassId = ref(''); const report = ref<ClassReport | null>(null); const loading = ref(true); const error = ref(''); const selectedClassLabel = computed(() => { const item = classes.value.find(entry => entry.id === selectedClassId.value); return item ? `${item.code} · ${item.name}` : 'Lớp học' }); function selectClass(id: string) { selectedClassId.value = id }; function changeClass() { selectedClassId.value = '' }; async function load() { if (!selectedClassId.value) { report.value = null; loading.value = false; return }; loading.value = true; try { report.value = await reportingApi.classSummary(selectedClassId.value) } catch (cause) { error.value = errorMessage(cause) || 'Không tải được báo cáo.' } finally { loading.value = false } }; async function boot() { try { classes.value = await academicsApi.classes(); loading.value = false } catch (cause) { error.value = errorMessage(cause) || 'Không tải được lớp học.'; loading.value = false } }; watch(selectedClassId, load); onMounted(boot)
</script>
